insert into public.exercises (id, slug, name, base_movement, category, equipment, metadata)
values
  ('50000000-0000-4000-8000-000000000001', 'sentadilla-pausa', 'Sentadilla con pausa', 'squat', 'strength', array['barbell','rack'], '{"section":"strength","summary":"Añade una pausa estable en el fondo para desarrollar fuerza desde una posición sin rebote.","focus":["fuerza","posición profunda","control"],"cues":["Pausa real sin relajarte","Mantén presión en todo el pie","Sube conservando el torso"]}'),
  ('50000000-0000-4000-8000-000000000002', 'sentadilla-frontal-pausa', 'Sentadilla frontal con pausa', 'squat', 'strength', array['barbell','rack'], '{"section":"strength","summary":"Refuerza la recepción y la recuperación de la cargada manteniendo una pausa en el fondo.","focus":["cuádriceps","rack frontal","fuerza de salida"],"cues":["Codos altos durante la pausa","No pierdas tensión abdominal","Empuja el suelo al salir"]}'),
  ('50000000-0000-4000-8000-000000000003', 'sentadilla-tempo', 'Sentadilla tempo', 'squat', 'strength', array['barbell','rack'], '{"section":"strength","summary":"Utiliza una bajada lenta para mejorar el control, la posición y el tiempo bajo tensión.","focus":["control excéntrico","piernas","técnica"],"cues":["Respeta el tempo indicado","Mantén el centro de masas estable","Acelera al subir"]}'),
  ('50000000-0000-4000-8000-000000000004', 'peso-muerto-arrancada', 'Peso muerto de arrancada', 'snatch', 'strength', array['barbell','plates'], '{"section":"strength","summary":"Desarrolla fuerza en el despegue con el agarre y las posiciones específicas de la arrancada.","focus":["despegue","cadena posterior","posición"],"cues":["Hombros por delante de la barra","Empuja con las piernas","Mantén la barra cerca"]}'),
  ('50000000-0000-4000-8000-000000000005', 'peso-muerto-cargada', 'Peso muerto de cargada', 'clean', 'strength', array['barbell','plates'], '{"section":"strength","summary":"Refuerza el primer tirón de la cargada sin buscar la extensión explosiva final.","focus":["piernas","despegue","fuerza específica"],"cues":["Espalda firme al despegar","Rodillas atrás con control","Termina en posición de potencia"]}'),
  ('50000000-0000-4000-8000-000000000006', 'press-sots', 'Press Sots', 'press', 'strength', array['barbell','rack'], '{"section":"strength","summary":"Combina estabilidad overhead, movilidad y fuerza de hombro desde sentadilla profunda.","focus":["overhead","movilidad","estabilidad"],"cues":["Mantén el pecho erguido","Presiona en línea vertical","Usa una carga ligera"]}'),

  ('60000000-0000-4000-8000-000000000001', 'movilidad-rack-frontal', 'Movilidad de rack frontal', 'mobility', 'mobility', array['barbell','rack'], '{"section":"mobility","summary":"Mejora la posición de codos, muñecas y hombros necesaria para recibir la cargada.","focus":["rack frontal","hombros","muñecas"],"cues":["Relaja el agarre","Eleva los codos progresivamente","No fuerces la muñeca"]}'),
  ('60000000-0000-4000-8000-000000000002', 'squat-to-stand', 'Squat to stand', 'mobility', 'mobility', array[]::text[], '{"section":"mobility","summary":"Alterna bisagra y sentadilla profunda para preparar tobillos, caderas e isquios.","focus":["cadera","isquios","sentadilla"],"cues":["Agarra las puntas de los pies","Extiende rodillas sin perder control","Termina con el pecho alto"]}'),
  ('60000000-0000-4000-8000-000000000003', 'sentadilla-cosaca', 'Sentadilla cosaca', 'mobility', 'mobility', array[]::text[], '{"section":"mobility","summary":"Desarrolla movilidad lateral de cadera y tobillo con control unilateral.","focus":["aductores","cadera","tobillo"],"cues":["Mantén apoyado el pie de trabajo","Desplaza la cadera lateralmente","Progresa sin dolor"]}'),

  ('70000000-0000-4000-8000-000000000001', 'arrancada-pausa-rodilla', 'Arrancada con pausa en rodilla', 'snatch', 'technique', array['barbell','plates'], '{"section":"snatch","summary":"Introduce una pausa a la altura de la rodilla para verificar equilibrio y posición antes de acelerar.","focus":["primer tirón","equilibrio","paciencia"],"cues":["Pausa con tensión","Peso en medio pie","Acelera después de la pausa"]}'),
  ('70000000-0000-4000-8000-000000000002', 'arrancada-pausa-hang', 'Arrancada desde hang con pausa', 'snatch', 'technique', array['barbell','plates'], '{"section":"snatch","summary":"Mantiene una pausa en hang para eliminar inercias y reforzar una extensión precisa.","focus":["hang","extensión","control"],"cues":["Fija la posición antes de salir","Barra pegada al muslo","Extiende y entra rápido"]}'),
  ('70000000-0000-4000-8000-000000000003', 'tiron-arrancada-pausa', 'Tirón de arrancada con pausa', 'snatch', 'pull', array['barbell','plates'], '{"section":"snatch","summary":"Refuerza posiciones concretas del tirón mediante una pausa antes de completar la extensión.","focus":["tirón","posición","fuerza"],"cues":["No descanses en la pausa","Conserva el ángulo del torso","Finaliza alto"]}'),
  ('70000000-0000-4000-8000-000000000004', 'arrancada-sin-pies', 'Arrancada sin mover los pies', 'snatch', 'technique', array['barbell','plates'], '{"section":"snatch","summary":"Reduce el salto lateral para mejorar el equilibrio, la extensión vertical y la conexión con el suelo.","focus":["equilibrio","extensión vertical","recepción"],"cues":["Coloca los pies en posición de recepción","Empuja vertical","Recibe sin desplazarte"]}'),
  ('70000000-0000-4000-8000-000000000005', 'arrancada-cadera', 'Arrancada desde cadera', 'snatch', 'technique', array['barbell','plates'], '{"section":"snatch","summary":"Aísla la fase final del segundo tirón y exige velocidad inmediata bajo la barra.","focus":["velocidad bajo barra","contacto","recepción"],"cues":["Empieza completamente extendido","Mantén la barra cerca","Entra con decisión"]}'),
  ('70000000-0000-4000-8000-000000000006', 'arrancada-deficit', 'Arrancada desde déficit', 'snatch', 'technique', array['barbell','plates'], '{"section":"snatch","summary":"Aumenta el recorrido inicial para reforzar el despegue y la paciencia durante el primer tirón.","focus":["despegue","fuerza de piernas","trayectoria"],"cues":["Usa un déficit pequeño","Mantén la posición inicial","No aceleres antes de tiempo"]}'),
  ('70000000-0000-4000-8000-000000000007', 'arrancada-tres-posiciones', 'Arrancada en tres posiciones', 'snatch', 'technique', array['barbell','plates'], '{"section":"snatch","summary":"Encadena arrancadas desde cadera, rodilla y suelo para consolidar posiciones y consistencia.","focus":["posiciones","consistencia","técnica"],"cues":["Recoloca antes de cada repetición","Mantén la misma trayectoria","Prioriza calidad sobre carga"]}'),
  ('70000000-0000-4000-8000-000000000008', 'complejo-arrancada', 'Complejo de arrancada', 'snatch', 'technique', array['barbell','plates'], '{"section":"snatch","summary":"Combina tirón, arrancada y sentadilla overhead para trabajar varias fases sin soltar la barra.","focus":["técnica","overhead","consistencia"],"cues":["Define el complejo antes de empezar","Mantén la técnica con fatiga","Usa una carga sostenible"]}'),

  ('80000000-0000-4000-8000-000000000001', 'cargada-pausa-rodilla', 'Cargada con pausa en rodilla', 'clean', 'technique', array['barbell','plates'], '{"section":"clean_and_jerk","summary":"Añade una pausa en la rodilla para reforzar equilibrio, tensión y transición en la cargada.","focus":["primer tirón","posición","rack frontal"],"cues":["Pausa sin perder tensión","Mantén hombros sobre la barra","Acelera al superar la rodilla"]}'),
  ('80000000-0000-4000-8000-000000000002', 'cargada-pausa-hang', 'Cargada desde hang con pausa', 'clean', 'technique', array['barbell','plates'], '{"section":"clean_and_jerk","summary":"Elimina el rebote en hang y obliga a producir potencia desde una posición controlada.","focus":["hang","potencia","recepción"],"cues":["Detén completamente la barra","Empuja el suelo","Codos rápidos al recibir"]}'),
  ('80000000-0000-4000-8000-000000000003', 'tiron-cargada-pausa', 'Tirón de cargada con pausa', 'clean', 'pull', array['barbell','plates'], '{"section":"clean_and_jerk","summary":"Refuerza el tirón de cargada con una pausa que expone pérdidas de posición o equilibrio.","focus":["tirón","fuerza","equilibrio"],"cues":["Barra cerca en la pausa","Presiona el suelo","Finaliza vertical"]}'),
  ('80000000-0000-4000-8000-000000000004', 'cargada-sin-pies', 'Cargada sin mover los pies', 'clean', 'technique', array['barbell','plates'], '{"section":"clean_and_jerk","summary":"Mejora la extensión vertical y la recepción equilibrada evitando el desplazamiento de los pies.","focus":["equilibrio","codos","recepción"],"cues":["Prepara los pies para recibir","Extiende vertical","Gira los codos con rapidez"]}'),
  ('80000000-0000-4000-8000-000000000005', 'cargada-tres-posiciones', 'Cargada en tres posiciones', 'clean', 'technique', array['barbell','plates'], '{"section":"clean_and_jerk","summary":"Encadena cargadas desde cadera, rodilla y suelo para repetir posiciones bajo fatiga controlada.","focus":["posiciones","rack frontal","consistencia"],"cues":["Reinicia cada posición","Conserva la trayectoria","No aumentes carga si pierdes velocidad"]}'),
  ('80000000-0000-4000-8000-000000000006', 'jerk-pausa-dip', 'Jerk con pausa en el dip', 'jerk', 'technique', array['barbell','rack'], '{"section":"clean_and_jerk","summary":"Detiene el dip antes de impulsar para corregir inclinaciones y mejorar la transmisión vertical.","focus":["dip","verticalidad","potencia"],"cues":["Pausa en la base del dip","Mantén el torso vertical","Empuja con las piernas"]}'),
  ('80000000-0000-4000-8000-000000000007', 'tall-jerk', 'Tall jerk', 'jerk', 'technique', array['barbell','rack'], '{"section":"clean_and_jerk","summary":"Aísla la entrada bajo la barra con un impulso mínimo para desarrollar velocidad de pies y bloqueo.","focus":["pies","bloqueo","velocidad"],"cues":["Empieza alto","Entra sin hundirte antes","Bloquea con decisión"]}'),
