  ('80000000-0000-4000-8000-000000000009', 'complejo-cargada-jerk', 'Complejo de cargada y jerk', 'clean-and-jerk', 'technique', array['barbell','plates'], '{"section":"clean_and_jerk","summary":"Combina variantes de cargada, sentadilla frontal y jerk para integrar el movimiento completo.","focus":["técnica","resistencia","competición"],"cues":["Planifica la secuencia","Recupera el rack antes del jerk","Mantén calidad en cada fase"]}')
